	//---------------------------------------------------------------------
	// A column this adapter is allowed to create.
	//
	// Used only while the adapter is creating the table. Afterwards the table itself is
	// the authority on what its columns are.

	export interface ColumnDefinition
	{
		Name: string;
		/** The SQL type. A missing or non-string value takes the adapter's default. */
		Type?: string;
		/** True for the column which carries the document identifier. */
		Key?: boolean;
	}


	//---------------------------------------------------------------------
	// The settings this adapter takes.

	export interface AdapterSettings
	{
		/** The name or address of the Oracle server. Defaults to `"localhost"`. */
		Server?: string;
		/** The listener port of the Oracle server. Defaults to `1521`. */
		Port?: number;
		/** The service name to connect to, which is the last part of the `host:port/service` connect string. It must already exist; this adapter never creates one. */
		Database: string;
		/** The schema holding the table. A schema is a user in Oracle, so this is an account name and it must already exist. Defaults to `the `UserName`, upper cased`. */
		Schema?: string;
		/** The name of the table to use. */
		Table: string;
		/** The column to treat as the document identifier. Empty means none. Defaults to `""`. */
		IdField?: string;
		/** The user to connect as. */
		UserName: string;
		/** That user's password. Pass an empty string for none - the setting itself is required. */
		Password: string;
		/** Allow the adapter to create the table and the columns it is told to create. It never creates a schema, and never adds a column because a document had a field. Defaults to `false`. */
		ModifySchema?: boolean;
		/** The column which stores the document as JSON text, as a `CLOB`. Empty means none, and then every field must already be a column. Created when missing if `ModifySchema` is `true`. Defaults to `""`. */
		PayloadColumn?: string;
		/** Store the whole document in the payload, making the other columns an index over it. When `false` the payload holds only the fields which have no column. Defaults to `false`. */
		PayloadSync?: boolean;
		/** Columns to create, as `{ Name, Type, Key }`. Used only when this adapter creates the table; afterwards the table itself is the authority. Defaults to `[]`. */
		Columns?: ColumnDefinition[];
	}


